import{_ as e,o,c as l,a2 as r}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"アクションメニューと即時プレビュー","description":"","frontmatter":{},"headers":[],"relativePath":"ja-JP/user-guide/actions-and-preview.md","filePath":"ja-JP/user-guide/actions-and-preview.md","lastUpdated":1787586465000}'),a={name:"ja-JP/user-guide/actions-and-preview.md"};function n(i,t,d,s,g,c){return o(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="アクションメニューと即時プレビュー" tabindex="-1">アクションメニューと即時プレビュー <a class="header-anchor" href="#アクションメニューと即時プレビュー" aria-label="Permalink to &quot;アクションメニューと即時プレビュー&quot;">​</a></h1><p>Lertaro は超高速なファイル検索だけでなく、充実したコンテキストアクション機能と強力なプレビューパネルを統合しており、エクスプローラーを開くことなくファイルの確認、管理、共有を行えます。</p><h2 id="_1-アクションメニューの詳細" tabindex="-1">1. アクションメニューの詳細 <a class="header-anchor" href="#_1-アクションメニューの詳細" aria-label="Permalink to &quot;1. アクションメニューの詳細&quot;">​</a></h2><p>検索結果（ファイル、フォルダー、アプリ、プラグイン項目）で <code>Ctrl+O</code> または方向キー <code>→</code> を押すと、コンテキストアクションメニューが展開されます。</p><h3 id="標準アクション一覧" tabindex="-1">標準アクション一覧 <a class="header-anchor" href="#標準アクション一覧" aria-label="Permalink to &quot;標準アクション一覧&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">アクション名</th><th style="text-align:left;">既定のキー</th><th style="text-align:left;">機能説明</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>開く</strong></td><td style="text-align:left;"><code>Enter</code></td><td style="text-align:left;">システムの既定プログラムでファイルを開くか、アプリを起動します。</td></tr><tr><td style="text-align:left;"><strong>エクスプローラーで表示</strong></td><td style="text-align:left;"><code>Ctrl+Enter</code></td><td style="text-align:left;">親フォルダーを開き、エクスプローラー上で対象ファイルを選択した状態で表示します。</td></tr><tr><td style="text-align:left;"><strong>管理者として実行</strong></td><td style="text-align:left;"><code>Ctrl+Shift+Enter</code></td><td style="text-align:left;">管理者権限でプログラムを実行します（実行可能ファイル、ショートカット、バッチ等に対応）。</td></tr><tr><td style="text-align:left;"><strong>フルパスをコピー</strong></td><td style="text-align:left;"><code>Ctrl+Shift+C</code></td><td style="text-align:left;">絶対パス（例: <code>D:\\Projects\\app.exe</code>）をクリップボードにコピーします。</td></tr><tr><td style="text-align:left;"><strong>ファイルの切り取り / コピー</strong></td><td style="text-align:left;"><code>Ctrl+X</code> / <code>Ctrl+C</code></td><td style="text-align:left;">ファイル自体をクリップボードに格納し、エクスプローラーや別フォルダーに直接貼り付け可能にします。</td></tr><tr><td style="text-align:left;"><strong>ここへ貼り付け</strong></td><td style="text-align:left;"><code>Ctrl+V</code></td><td style="text-align:left;">選択対象がフォルダーの場合、クリップボード内のファイルをそのフォルダー内に貼り付けます。</td></tr><tr><td style="text-align:left;"><strong>削除（ごみ箱へ移動）</strong></td><td style="text-align:left;"><code>Delete</code></td><td style="text-align:left;">選択したファイルやフォルダーをごみ箱へ安全に移動します。</td></tr><tr><td style="text-align:left;"><strong>完全に削除</strong></td><td style="text-align:left;"><code>Shift+Delete</code></td><td style="text-align:left;">選択項目を完全に削除します（復元不可、確認ダイアログが表示されます）。</td></tr><tr><td style="text-align:left;"><strong>Windows 右クリックメニュー</strong></td><td style="text-align:left;">—</td><td style="text-align:left;">Windows エクスプローラーの標準コンテキストメニュー（送る、サードパーティ製ツールの項目を含む）を展開します。</td></tr></tbody></table><h3 id="アクションメニューの操作と絞り込み" tabindex="-1">アクションメニューの操作と絞り込み <a class="header-anchor" href="#アクションメニューの操作と絞り込み" aria-label="Permalink to &quot;アクションメニューの操作と絞り込み&quot;">​</a></h3><ul><li><strong>入力して即時絞り込み</strong>：アクションメニューが開いた状態で文字を入力すると、アクション名で素早く絞り込めます（例: <code>copy</code> と入力してコピー関連の操作を即座に抽出）。</li><li><strong>階層ナビゲーション</strong>：サブメニューを持つ項目（「送る」など）で <code>→</code> または <code>Enter</code> を押して下の階層に進み、<code>←</code> またはテキストが空の状態で <code>Backspace</code> を押すと親階層に戻ります。</li><li><strong>メニューを閉じる</strong>：<code>Escape</code> を押すとアクションメニューが閉じ、検索結果一覧に戻ります。</li></ul><h2 id="_2-メインウィンドウの一覧機能" tabindex="-1">2. メインウィンドウの一覧機能 <a class="header-anchor" href="#_2-メインウィンドウの一覧機能" aria-label="Permalink to &quot;2. メインウィンドウの一覧機能&quot;">​</a></h2><p>メイン検索ウィンドウ（<code>Ctrl+F</code>）は、大量のファイル管理と詳細なブラウジングのために設計されています。</p><ul><li><strong>パス列のダブルクリック移動</strong>：結果一覧の <strong>名前</strong> 列をダブルクリックするとファイルが開き、<strong>パス</strong> 列をダブルクリックするとそのファイルが存在する親フォルダーが直接開きます。</li><li><strong>ストリーミング結果表示</strong>：数百万件のファイルをスキャンする際も、インデックスエンジンから届いた結果がリアルタイムに順次一覧へ追加されます。検索全体の完了を待つことなく即座に操作が可能です。</li><li><strong>ループナビゲーション</strong>：先頭行で <code>↑</code> を押すと末尾行へ、末尾行で <code>↓</code> を押すと先頭行へループ移動します。</li><li><strong>ウィンドウのドラッグ移動とサイズ記憶</strong>：ウィンドウ上部の余白部分はドラッグバーとして機能し、手動で調整したウィンドウサイズは次回起動時にも自動的に保持されます。</li></ul><h2 id="_3-quicklook-即時プレビュー機能" tabindex="-1">3. QuickLook 即時プレビュー機能 <a class="header-anchor" href="#_3-quicklook-即時プレビュー機能" aria-label="Permalink to &quot;3. QuickLook 即時プレビュー機能&quot;">​</a></h2><p>任意の検索結果で <code>Alt+P</code> を押すと、検索ウィンドウの横に強力なプレビューパネルが表示されます。</p><h3 id="多彩なファイル形式に対応" tabindex="-1">多彩なファイル形式に対応 <a class="header-anchor" href="#多彩なファイル形式に対応" aria-label="Permalink to &quot;多彩なファイル形式に対応&quot;">​</a></h3><ul><li><strong>画像とベクター形式</strong>：JPG、PNG、GIF（アニメーション自動再生）、BMP、WebP、ICO、SVG などの高解像度プレビュー。</li><li><strong>ドキュメントとコード構文</strong>：TXT、Markdown、JSON、XML、YAML、C#、Python、JS、HTML などのシンタックスハイライト表示。</li><li><strong>音声・動画の即時再生</strong>：MP4、MKV、AVI、MOV、WMV、MP3、WAV、FLAC、WMA などのメディアファイルはプレビューを開くと<strong>自動的に再生が開始</strong>され、テーマ連動のミニ再生バー（再生/一時停止、シークバー、再生時間、ミュート）が表示されます。項目の切り替えで即座に停止します。</li><li><strong>フォルダー構造の確認</strong>：フォルダーを選択すると、直下のアイテム上位 30 件がアイコン・サイズ付きで表示されます（隠しファイルやシステムファイルは除外）。</li></ul><h3 id="レイアウトとダイアログの自動回避" tabindex="-1">レイアウトとダイアログの自動回避 <a class="header-anchor" href="#レイアウトとダイアログの自動回避" aria-label="Permalink to &quot;レイアウトとダイアログの自動回避&quot;">​</a></h3><ul><li><strong>画面範囲の自動調整</strong>：プレビューサイズは <a href="./settings/general.html#プレビュー"><strong>設定 → 一般 → プレビュー</strong></a> で変更可能で、画面外にはみ出さないよう自動制御されます。</li><li><strong>ネイティブダイアログの自動回避</strong>：パスワード保護された Office 文書などをプレビューする際、パスワード入力ダイアログが表示されると Lertaro は一時的にウィンドウを隠し、操作完了後に自動復帰します。</li><li><strong>プレビューからのドラッグ＆ドロップ</strong>：プレビューパネルの上部をドラッグすることで、プレビュー中のファイルを外部アプリやエクスプローラーへ直接ドロップできます。</li></ul><h2 id="_4-プラグインのリッチテキスト・対話型プレビュー" tabindex="-1">4. プラグインのリッチテキスト・対話型プレビュー <a class="header-anchor" href="#_4-プラグインのリッチテキスト・対話型プレビュー" aria-label="Permalink to &quot;4. プラグインのリッチテキスト・対話型プレビュー&quot;">​</a></h2><p>QuickLook はローカルファイルだけでなく、プラグインによる対話型プレビューにも対応しています。</p><ul><li><strong>テーマ適応型リッチテキスト</strong>：WebView2 およびネイティブコンポーネントで描画され、ダーク/ライトテーマに自動追従し、高コントラストフォントと半透明スクロールバーで美しく表示されます。</li><li><strong>多彩なプラグインカード</strong>：辞書検索カード、リアルタイム天気予報、Web スナップショット、API レスポンス確認などの対話型パネルをサポートします。</li></ul><h2 id="_5-サードパーティ製-quicklook-との連携-任意" tabindex="-1">5. サードパーティ製 QuickLook との連携（任意） <a class="header-anchor" href="#_5-サードパーティ製-quicklook-との連携-任意" aria-label="Permalink to &quot;5. サードパーティ製 QuickLook との連携（任意）&quot;">​</a></h2><p>独立したオープンソースツール <strong>QuickLook</strong>（<a href="https://github.com/QL-Win/QuickLook" target="_blank" rel="noreferrer">GitHub の QL-Win/QuickLook</a>）をお使いの場合、<a href="./settings/plugins.html"><strong>設定 → プラグイン</strong></a> で <strong>QuickLook ブリッジ</strong> プラグインを有効化できます。</p><ul><li><strong>プレビューの委譲</strong>：ローカルの名前付きパイプ経由で外部の QuickLook プロセスに接続し、プレビューウィンドウを Lertaro の横に吸着表示します。</li><li><strong>自動フォールバック</strong>：外部の QuickLook が起動していない場合は、Lertaro 内蔵のプレビューエンジンへ自動的に切り替わります。</li></ul>',23)])])}const f=e(a,[["render",n]]);export{u as __pageData,f as default};
